+export const DIGIT: string;
+export const LIST: string;
+export const CALC: string;
+
+// ---- lab-link ----
+export interface LabLink {
+  grammar?: string;
+  input?: string;
+  preset?: string;
+}
+export function labGrammarHref(
+  base: string,
